program='''from collections import Counter

def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in seen and grid[nx][ny] == v:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            objects.append({'color': v, 'cells': cells})

    # Follow the chain of touching objects, starting at its highest object.
    remaining = set(range(len(objects)))
    current = min(remaining, key=lambda i: (min(r for r, c in objects[i]['cells']), min(c for r, c in objects[i]['cells'])))
    order = []
    while remaining:
        order.append(current)
        remaining.remove(current)
        current_cells = set(objects[current]['cells'])
        adjacent = []
        for i in remaining:
            if any((r + dr, c + dc) in current_cells for r, c in objects[i]['cells'] for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                adjacent.append(i)
        if adjacent:
            current = min(adjacent, key=lambda i: (min(r for r, c in objects[i]['cells']), min(c for r, c in objects[i]['cells'])))
        elif remaining:
            current = min(remaining, key=lambda i: (min(r for r, c in objects[i]['cells']), min(c for r, c in objects[i]['cells'])))
    return [[objects[i]['color']] for i in order for _ in objects[i]['cells']]
'''
